JSRuntime *JS_NewRuntime2(const JSMallocFunctions *mf, void *opaque)
{
    JSRuntime *rt;
    JSMallocState ms;
    JSString *illegal_access;

    memset(&ms, 0, sizeof(ms));
    ms.opaque = opaque;
    ms.malloc_limit = 0;

    rt = mf->js_calloc(opaque, 1, sizeof(JSRuntime));
    if (!rt)
        return NULL;
    rt->execution_context = JS_UNDEFINED;
    rt->continuation_preserved_embedder_data = JS_UNDEFINED;
    rt->pi_javascript_execution_allowed = true;
    rt->pi_javascript_execution_error = JS_UNDEFINED;
#ifdef CONFIG_ATOMICS
    atomic_store(&rt->pi_termination_requested, false);
#endif

JSValue JS_ThrowOutOfMemory(JSContext *ctx)
{
    JSRuntime *rt = ctx->rt;
    if (ctx->pi_compiler_diagnostic && JS_HasException(ctx))
        return JS_EXCEPTION;
    if (ctx->pi_compiler_diagnostic)
        ctx->pi_compiler_diagnostic->allocation_failed = true;
    if (!rt->in_out_of_memory) {
        rt->in_out_of_memory = true;
        JS_ThrowInternalError(ctx, "out of memory");
        rt->in_out_of_memory = false;
    }
    return JS_EXCEPTION;
}

static JSString *js_alloc_string(JSContext *ctx, int max_len, int is_wide_char)
{
    JSString *p;
    p = js_alloc_string_rt(ctx->rt, max_len, is_wide_char);
    if (unlikely(!p)) {
        JS_ThrowOutOfMemory(ctx);
        return NULL;
    }
    return p;
}

JSValue JS_NewStringUTF16(JSContext *ctx, const uint16_t *buf, size_t len)
{
    JSString *str;

    if (unlikely(!len))
        return js_empty_string(ctx->rt);
    if (unlikely(len > JS_STRING_LEN_MAX))
        return JS_ThrowRangeError(ctx, "invalid string length");

    str = js_alloc_string(ctx, len, 1);
    if (unlikely(!str))
        return JS_EXCEPTION;
    memcpy(str16(str), buf, len * sizeof(*buf));
    return JS_MKPTR(JS_TAG_STRING, str);
}
